def calculate(a_value: float) -> Result[float]:
    if not isinstance(a_value, (int, float)):
        return Result.failure(f'Expected number, got {type(a_value).__name__}')
    if a_value < 0:
        return Result.failure('Value must be non-negative')
    return Result.success(a_value * 2)
